file.content:
        return "it is empty; expected 64 lowercase hexadecimal characters"
    if value != value.strip() or any(char in " \t\r\n" for char in value):
        return (
            "it contains surrounding or embedded whitespace; expected 64 "
            "lowercase hexadecimal characters without spaces"
        )
    if len(value) != 64:
        return (
            f"it has {len(value)} characters instead of 64; expected 64 "
            "lowercase hexadecimal characters"
        )
    if _DIGEST_RE.fullmatch(value) is None:
        # Length is exactly 64 here, so every remaining problem is a
        # non-hex or uppercase character.
        return (
            "it must contain only lowercase hexadecimal characters "
            "(digits 0-9 and letters a-f)"
        )
    return None


def category_key(label: Any) -> Any:
    """Stratum key for a manifest label value.

    ``None`` and the empty string both mean "unlabeled", matching
    :meth:`DatasetStore.summary`; any other label is taken literally.
    """
    if label is None or label == "":
        return UNLABELED
    return label


def category_name(key: Any) -> str:
    """Render a stratum key for JSON output.

    The unlabeled stratum renders as the empty string (which mirrors the
    manifest's empty-label meaning); a genuine class literally named
    ``"unlabeled"`` therefore stays distinguishable.
    """
    return "" if key is UNLABELED else str(key)

class BatchCliTest(StoreHarness):
    def run_cli(self, *arguments: str) -> subprocess.CompletedProcess:
        return subprocess.run(
            [sys.executable, "-m", "vision_workbench", *arguments],
            cwd=REPO_ROOT,
            text=True,
            capture_output=True,
            check=False,
        )

    def test_cli_batch_label_history_undo(self) -> None:
        d = self.add_sample("cat")
        batch_path = self.root.parent / "batch.json"
        batch_path.write_text(
            json.dumps(
                {
                    "batch": "cli1",
                    "changes": [
                        {"sha256": d, "old": "cat", "new": "狗"}
                    ],
                }
            ),
            encoding="utf-8",
        )

        submitted = self.run_cli("batch", str(self.root), str(batch_path))
        self.assertEqual(submitted.returncode, 0, submitted.stderr)
        body = json.loads(submitted.stdout)
        self.assertEqual(body["status"], "applied")
        self.assertEqual(body["changed"], 1)

class BatchSplitInteractionTest(StoreHarness):
    def test_label_changes_leave_existing_splits_unchanged(self) -> None:
        d = self.add_sample("cat")
        plan = self.store.create_split("p", 0, [1, 0, 0]).plan
        self.submit("b1", (d, "cat", "dog"))
        reopened = self.store.get_split("p")
        self.assertEqual(reopened, plan)
        self.assertEqual(reopened["samples"]["distribution"], {"cat": 1})
        self.assertEqual(
            reopened["sets"]["train"]["members"][0]["label"], "cat"
        )

    def test_new_split_uses_current_labels_and_reuse_rules_apply(self) -> None:
        d = self.add_sample("cat")
        first = self.store.create_split("p", 0, [1, 0, 0])
        self.assertTrue(first.created)
        self.submit("b1", (d, "cat", "dog"))

        # Reusing the same name now conflicts (labels differ).
        with self.assertRaises(Exception):
            self.store.create_split("p", 0, [1, 0, 0])

        # A new plan uses the current label.
        second = self.store.create_split("p2", 0, [1, 0, 0])
        self.assertEqual(second.plan["samples"]["distribution"], {"dog": 1})


